create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;
create extension if not exists pgcrypto with schema extensions;
create table private.versions (owner_id uuid primary key, version bigint not null default 0);
create table public.sessions (id uuid not null, owner_id uuid not null, data jsonb not null, primary key(owner_id,id));
create table public.imports (id uuid not null, owner_id uuid not null, session_id uuid not null, original bytea not null, file_hash text not null, content_hash text not null, parser_version text not null, primary key(owner_id,id), foreign key(owner_id,session_id) references public.sessions(owner_id,id), unique(owner_id,session_id), unique(owner_id,file_hash), unique(owner_id,content_hash));
create table public.shots (id uuid not null, owner_id uuid not null, session_id uuid not null, payload jsonb not null, primary key(owner_id,id), foreign key(owner_id,session_id) references public.sessions(owner_id,id));
create unique index shots_session_row on public.shots (owner_id, session_id, (payload->>'rowIndex'));
create table public.reviews (shot_id uuid not null, owner_id uuid not null, state jsonb not null, revision integer not null check(revision>=0), primary key(owner_id,shot_id), foreign key(owner_id,shot_id) references public.shots(owner_id,id));
create table public.review_events (id uuid not null, owner_id uuid not null, shot_id uuid not null, before_state jsonb not null, after_state jsonb not null, created_at timestamptz not null default clock_timestamp(), undone boolean not null default false, primary key(owner_id,id), foreign key(owner_id,shot_id) references public.shots(owner_id,id));
do $$ declare t text; begin foreach t in array array['sessions','imports','shots','reviews','review_events'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from public, anon, authenticated',t); execute format('grant select on public.%I to authenticated',t); execute format('create policy owner_read on public.%I for select to authenticated using ((select auth.uid()) = owner_id)',t); end loop; end $$;
create function private.owner() returns uuid language plpgsql stable set search_path='' as $$ declare u uuid := auth.uid(); begin if u is null then raise exception 'Authentication required'; end if; return u; end $$;
create function private.lock_owner() returns uuid language plpgsql security definer set search_path='' as $$ declare u uuid := private.owner(); begin perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(u::text, 0)); insert into private.versions(owner_id) values(u) on conflict do nothing; return u; end $$;
create function private.bump(u uuid) returns void language sql set search_path='' as $$ update private.versions set version=version+1 where owner_id=u $$;
create function private.valid_review(r jsonb) returns boolean language sql immutable set search_path='' as $$ select coalesce(jsonb_typeof(r)='object' and r->>'intent' in ('full','partial','unknown') and r->>'contact' in ('typical','mishit','uncertain') and (r->'club'->>'kind' in ('unreviewed','confirmed') or (r->'club'->>'kind'='corrected' and jsonb_typeof(r->'club'->'club')='string' and length(trim(r->'club'->>'club')) between 1 and 30)) and (r->'exclusion'->>'kind'='included' or (r->'exclusion'->>'kind'='excluded' and jsonb_typeof(r->'exclusion'->'reason')='string' and length(trim(r->'exclusion'->>'reason')) between 1 and 500)),false) $$;
create function private.js_trim(v text) returns text language sql immutable set search_path='' as $$ select btrim(v, chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279)) $$;
create function private.valid_shot(s jsonb) returns boolean language plpgsql immutable set search_path='' as $$ declare k text; v jsonb; n double precision; keys text[] := array['carryRange','flatCarryRange','carryPremium','flatCarryPremium','totalRange','flatTotalRange','totalPremium','flatTotalPremium','apexRange','apexPremium','speedRange','speedPremium','launchRange','launchPremium','launchDirection','fromCentre','curve','proximity','target','strokesGained']; begin
 if not coalesce(jsonb_typeof(s)='object' and jsonb_typeof(s->'rowIndex')='number' and (s->>'rowIndex') ~ '^[1-9][0-9]*$' and jsonb_typeof(s->'sourceNumber')='string' and jsonb_typeof(s->'recordedClub')='string' and jsonb_typeof(s->'raw')='object' and jsonb_typeof(s->'measurements')='object',false) then return false; end if;
 if jsonb_typeof(s->'raw'->'Shot #') is distinct from 'string' or jsonb_typeof(s->'raw'->'Club') is distinct from 'string' or s->>'sourceNumber' is distinct from s->'raw'->>'Shot #' or s->>'recordedClub' is distinct from coalesce(nullif(private.js_trim(s->'raw'->>'Club'),''),'?') then return false; end if;
 for k,v in select * from jsonb_each(s->'raw') loop if jsonb_typeof(v)<>'string' then return false; end if; end loop;
 if (select count(*) from jsonb_object_keys(s->'measurements'))<>cardinality(keys) then return false; end if;
 for k,v in select * from jsonb_each(s->'measurements') loop if not k=any(keys) or jsonb_typeof(v) not in ('number','null') then return false; end if; if jsonb_typeof(v)='number' then n:=(v#>>'{}')::double precision; if (k not in ('launchDirection','fromCentre','curve','strokesGained','launchRange','launchPremium') and n<0) or (k like 'launch%' and abs(n)>90) then return false; end if; end if; end loop; return true; exception when others then return false; end $$;
create function private.valid_session(s jsonb) returns boolean language plpgsql stable set search_path='' as $$ declare d date; begin if jsonb_typeof(s)<>'object' or (s->>'date') !~ '^\d{4}-\d{2}-\d{2}$' then return false; end if; d := (s->>'date')::date; return coalesce(to_char(d,'YYYY-MM-DD')=s->>'date' and (s->'time'='null'::jsonb or (s->>'time' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')) and jsonb_typeof(s->'venue')='string' and length(s->>'venue')<=200 and jsonb_typeof(s->'notes')='string' and length(s->>'notes')<=2000 and jsonb_typeof(s->'archived')='boolean' and jsonb_typeof(s->'filename')='string' and (s->>'revision') ~ '^[0-9]+$',false); exception when others then return false; end $$;
create function private.js_sort_key(v text) returns text language plpgsql immutable set search_path='' as $$ declare out text:=''; c integer; begin for i in 1..char_length(v) loop c:=ascii(substr(v,i,1)); if c<=65535 then out:=out||lpad(to_hex(c),4,'0'); else c:=c-65536; out:=out||lpad(to_hex(55296+(c/1024)),4,'0')||lpad(to_hex(56320+(c%1024)),4,'0'); end if; end loop; return out; end $$;
create function private.canonical_hash(p jsonb) returns text language plpgsql stable set search_path='' as $$ declare headers text[]; row jsonb; headtext text; rows text:=''; cells text; begin
 if jsonb_typeof(p->'headers') is distinct from 'array' then raise exception 'Invalid headers'; end if;
 if exists(select 1 from jsonb_array_elements(p->'headers') h where jsonb_typeof(h)<>'string' or private.js_trim(h#>>'{}')<>h#>>'{}' or h#>>'{}'='') then raise exception 'Invalid headers'; end if;
 select array_agg(h order by private.js_sort_key(h) collate "C") into headers from jsonb_array_elements_text(p->'headers') h;
 if headers is null or cardinality(headers)<>(select count(distinct h) from unnest(headers) h) or not headers @> array['Shot #','Club','Carry Dist. Range (m)'] then raise exception 'Invalid headers'; end if;
 select string_agg(to_json(h)::text,',' order by private.js_sort_key(h) collate "C") into headtext from unnest(headers) h;
 for row in select value from jsonb_array_elements(p->'shots') loop
 if jsonb_typeof(row->'raw') is distinct from 'object' or (select count(*) from jsonb_object_keys(row->'raw'))<>cardinality(headers) or exists(select 1 from unnest(headers) h where jsonb_typeof(row->'raw'->h) is distinct from 'string') then raise exception 'Invalid raw cells'; end if;
 select string_agg(to_json(row->'raw'->>h)::text,',' order by private.js_sort_key(h) collate "C") into cells from unnest(headers) h;
 rows:=rows||case when rows='' then '' else ',' end||'['||cells||']'; end loop;
 return encode(extensions.digest(convert_to('[['||headtext||'],['||rows||']]','UTF8'),'sha256'),'hex'); end $$;
create function private.measurement(raw text, key text) returns double precision language plpgsql immutable set search_path='' as $$
declare v text:=private.js_trim(raw); m text[]; n double precision; direction text; begin
 if v='' or v='--' then return null; end if;
 if key in ('curve','launchDirection','fromCentre') then
   m:=regexp_match(v, '^([+-]?[0-9]+(\.[0-9]+)?)[[:space:]]*°?[[:space:]]*([LRlr])?$');
 else
   m:=regexp_match(v, '^([+-]?[0-9]+(\.[0-9]+)?)[[:space:]]*°?$');
 end if;
 if m is null then return null; end if;
 begin n:=m[1]::double precision; exception when numeric_value_out_of_range then
   if abs(m[1]::numeric)<1e-323::numeric then n:=0; else return null; end if;
 end;
 if key not in ('launchDirection','fromCentre','curve','strokesGained','launchRange','launchPremium') and n<0 then return null; end if;
 if key like 'launch%' and abs(n)>90 then return null; end if;
 direction:=m[3]; if direction is not null then n:=abs(n)*case when upper(direction)='L' then -1 else 1 end; end if;
 return n;
end $$;
create function private.validate_source(original bytea, preview jsonb, parser_version text) returns void language plpgsql stable set search_path='' as $$
declare
 source text; sample text; cr_parts text[]; newline text; n_first integer; cr_first integer; crlf_count integer; chars text[]; i integer:=1; size integer; ch text; nxt text; field text; field_start integer:=1; field_end integer; field_quoted boolean:=false; fields text[]:=array[]::text[];
 quoted boolean:=false; closed boolean:=false; at_start boolean:=true; row_no integer:=0; headers text[]; actual jsonb; shot jsonb; k text; h text; expected double precision; got double precision; value jsonb; nonempty text;
 mapping jsonb := '{"carryRange":"Carry Dist. Range (m)","flatCarryRange":"Flat Carry Dist. Range (m)","carryPremium":"Carry Dist. Premium (m)","flatCarryPremium":"Flat Carry Dist. Premium (m)","totalRange":"Total Dist. Range (m)","flatTotalRange":"Flat Total Dist. Range (m)","totalPremium":"Total Dist. Premium (m)","flatTotalPremium":"Flat Total Dist. Premium (m)","apexRange":"Apex (m)","apexPremium":"Apex (m) Premium","speedRange":"Ball Speed (kph)","speedPremium":"Ball Speed (kph) Premium","launchRange":"Launch Angle (deg)","launchPremium":"Launch Angle (deg) Premium","launchDirection":"Launch Direction","fromCentre":"From Centre (m)","curve":"Curve","proximity":"Prox to Hole (m)","target":"Target (m)","strokesGained":"Strokes Gained"}'::jsonb;
begin
 if parser_version is distinct from 'inrange-1' then raise exception 'Unsupported parser version'; end if;
 source:=convert_from(original,'UTF8'); if left(source,1)=chr(65279) then source:=substr(source,2); end if;
 sample:=regexp_replace(left(source,1048576),'"[^"]*"','','g'); cr_parts:=string_to_array(sample,E'\r'); n_first:=strpos(sample,E'\n'); cr_first:=strpos(sample,E'\r');
 if cr_first=0 or (n_first>0 and n_first<cr_first) then newline:=E'\n'; else
  select count(*) into crlf_count from unnest(cr_parts) x where left(x,1)=E'\n';
  if crlf_count>=cardinality(cr_parts)/2.0 then newline:=E'\r\n'; else newline:=E'\r'; end if;
 end if;
 chars:=regexp_split_to_array(source,''); size:=coalesce(cardinality(chars),0);
 while i<=size+1 loop
  ch:=case when i<=size then chars[i] else null end; nxt:=case when i<size then chars[i+1] else null end;
  if quoted then
   if ch is null then raise exception 'Unclosed CSV quote';
   elsif ch='"' then if nxt='"' then i:=i+1; else quoted:=false; closed:=true; field_end:=i-1; end if;
   end if;
  elsif ch='"' and at_start and not closed then quoted:=true; field_quoted:=true; field_start:=i+1; at_start:=false;
  elsif ch=',' or ch is null or (ch=left(newline,1) and (length(newline)=1 or nxt=E'\n')) then
   if not field_quoted then field_end:=i-1; end if; field:=coalesce(array_to_string(chars[field_start:field_end],''),''); if field_quoted then field:=replace(field,'""','"'); end if;
   fields:=array_append(fields,field); at_start:=true; closed:=false; field_quoted:=false;
   if ch is null or (ch=left(newline,1) and (length(newline)=1 or nxt=E'\n')) then
    if ch is not null and length(newline)=2 then i:=i+1; end if;
    nonempty:=private.js_trim(array_to_string(fields,''));
    if nonempty<>'' then
     if headers is null then
      select array_agg(private.js_trim(x) order by ord) into headers from unnest(fields) with ordinality as t(x,ord);
      if cardinality(headers)<>jsonb_array_length(preview->'headers') or exists(select 1 from unnest(headers) hdr where not (preview->'headers' ? hdr)) then raise exception 'CSV headers do not match'; end if;
     else
      row_no:=row_no+1; if row_no>jsonb_array_length(preview->'shots') or cardinality(fields)<>cardinality(headers) then raise exception 'CSV rows do not match'; end if;
      select jsonb_object_agg(headers[n],fields[n]) into actual from generate_subscripts(headers,1) n;
      shot:=preview->'shots'->(row_no-1);
      if not private.valid_shot(shot) or (shot->>'rowIndex')::integer<>row_no or shot->'raw' is distinct from actual then raise exception 'CSV cells do not match'; end if;
      for k,h in select e.key,e.value from jsonb_each_text(mapping) e loop
       expected:=private.measurement(coalesce(actual->>h,''),k); value:=shot->'measurements'->k;
       if value='null'::jsonb then got:=null; else got:=(value#>>'{}')::double precision; end if;
       if got is distinct from expected then raise exception 'CSV measurement does not match'; end if;
      end loop;
     end if;
    end if;
    fields:=array[]::text[];
   end if;
   field_start:=i+1;
  elsif closed and private.js_trim(ch)='' then null;
  elsif closed then raise exception 'Invalid text after CSV quote';
  else at_start:=false;
  end if;
  i:=i+1;
 end loop;
 if headers is null or row_no=0 or row_no<>jsonb_array_length(preview->'shots') then raise exception 'CSV row count does not match'; end if;
end $$;
create function private.commit_import(p_input jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); p jsonb:=p_input->'preview'; raw_bytes bytea; existing uuid; sid uuid:=extensions.gen_random_uuid(); iid uuid:=extensions.gen_random_uuid(); s jsonb; rev jsonb; n integer:=0; club text; session_data jsonb; begin
 if not coalesce(jsonb_typeof(p_input->'confirmedFull')='boolean' and jsonb_typeof(p_input->'allowSameDay')='boolean' and jsonb_typeof(p->'shots')='array' and jsonb_array_length(p->'shots') between 1 and 20000 and jsonb_typeof(p->'originalBase64')='string' and (p->>'fileHash') ~ '^[0-9a-f]{64}$' and (p->>'contentHash') ~ '^[0-9a-f]{64}$' and jsonb_typeof(p->'parserVersion')='string',false) then raise exception 'Invalid import'; end if;
 if private.canonical_hash(p)<>p->>'contentHash' then raise exception 'Invalid content hash'; end if; raw_bytes:=decode(p->>'originalBase64','base64'); if octet_length(raw_bytes)>5242880 or encode(extensions.digest(raw_bytes,'sha256'),'hex')<>p->>'fileHash' then raise exception 'Invalid file hash or size'; end if; perform private.validate_source(raw_bytes,p,p->>'parserVersion');
 select session_id into existing from public.imports where owner_id=u and (file_hash=p->>'fileHash' or content_hash=p->>'contentHash') limit 1; if existing is not null then return jsonb_build_object('sessionId',existing,'duplicate',true); end if;
 session_data:=jsonb_build_object('id',sid,'date',p_input->'date','time',p_input->'time','venue',p_input->'venue','notes',p_input->'notes','archived',false,'filename',p_input->'filename','revision',0); if not private.valid_session(session_data) then raise exception 'Invalid session'; end if;
 if not (p_input->>'allowSameDay')::boolean and exists(select 1 from public.sessions where owner_id=u and data->>'date'=p_input->>'date') then raise exception 'Same-day import requires acknowledgement'; end if;
 insert into public.sessions values(sid,u,session_data); insert into public.imports values(iid,u,sid,raw_bytes,p->>'fileHash',p->>'contentHash',p->>'parserVersion');
 for s in select value from jsonb_array_elements(p->'shots') loop n:=n+1; if not private.valid_shot(s) or (s->>'rowIndex')::integer<>n then raise exception 'Invalid shot row'; end if; club:=trim(s->>'recordedClub'); rev:=jsonb_build_object('intent',case when (p_input->>'confirmedFull')::boolean and club !~* '^(PW|SW|GW|LW|AW|UW|W|[0-9]{2}°?)$' and lower(club) not in ('','?','unknown','--') then 'full' else 'unknown' end,'contact','uncertain','club',jsonb_build_object('kind','unreviewed'),'exclusion',jsonb_build_object('kind','included')); with x as (insert into public.shots values(extensions.gen_random_uuid(),u,sid,s) returning id) insert into public.reviews select id,u,rev,0 from x; end loop;
 perform private.bump(u); return jsonb_build_object('sessionId',sid,'duplicate',false); end $$;
create function private.apply_reviews(p_changes jsonb) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); c jsonb; old public.reviews%rowtype; begin if not coalesce(jsonb_typeof(p_changes)='array' and jsonb_array_length(p_changes) between 1 and 20000,false) then raise exception 'Invalid changes'; end if; for c in select value from jsonb_array_elements(p_changes) loop if not private.valid_review(c->'review') or not coalesce((c->>'expectedRevision') ~ '^[0-9]+$',false) then raise exception 'Invalid review'; end if; select * into old from public.reviews where shot_id=(c->>'shotId')::uuid and owner_id=u for update; if not found or old.revision<>(c->>'expectedRevision')::integer then raise exception 'Review conflict'; end if; update public.reviews set state=c->'review',revision=revision+1 where shot_id=old.shot_id and owner_id=u; insert into public.review_events(id,owner_id,shot_id,before_state,after_state) values(extensions.gen_random_uuid(),u,old.shot_id,old.state,c->'review'); end loop; perform private.bump(u); end $$;
create function private.undo_reviews(p_shots jsonb) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); c jsonb; old public.reviews%rowtype; e public.review_events%rowtype; begin if not coalesce(jsonb_typeof(p_shots)='array' and jsonb_array_length(p_shots) between 1 and 20000,false) then raise exception 'Invalid undo'; end if; for c in select value from jsonb_array_elements(p_shots) loop select * into old from public.reviews where shot_id=(c->>'shotId')::uuid and owner_id=u for update; if not found or not coalesce((c->>'expectedRevision') ~ '^[0-9]+$',false) or old.revision<>(c->>'expectedRevision')::integer then raise exception 'Review conflict'; end if; select * into e from public.review_events where shot_id=old.shot_id and owner_id=u and not undone order by created_at desc,id desc limit 1 for update; if not found then raise exception 'Nothing to undo'; end if; update public.review_events set undone=true where id=e.id and owner_id=u; update public.reviews set state=e.before_state,revision=revision+1 where shot_id=old.shot_id and owner_id=u; insert into public.review_events(id,owner_id,shot_id,before_state,after_state,undone) values(extensions.gen_random_uuid(),u,old.shot_id,old.state,e.before_state,true); end loop; perform private.bump(u); end $$;
create function private.update_session(p_session jsonb) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); old jsonb; begin if not private.valid_session(p_session) then raise exception 'Invalid session'; end if; select data into old from public.sessions where id=(p_session->>'id')::uuid and owner_id=u for update; if old is null or old->>'revision'<>p_session->>'revision' then raise exception 'Session conflict'; end if; if old->>'filename'<>p_session->>'filename' then raise exception 'Filename is immutable'; end if; update public.sessions set data=jsonb_set(p_session,'{revision}',to_jsonb((old->>'revision')::integer+1)) where id=(p_session->>'id')::uuid and owner_id=u; perform private.bump(u); end $$;
create function private.dataset_version() returns bigint language sql stable security definer set search_path='' as $$ select coalesce((select version from private.versions where owner_id=private.owner()),0) $$;
create function private.dataset_page(p_table text,p_offset integer,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare u uuid:=private.owner(); result jsonb; begin if p_offset is null or p_limit is null or p_offset<0 or p_limit not between 1 and 1000 then raise exception 'Invalid page'; end if; case p_table when 'sessions' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,data from public.sessions where owner_id=u order by id offset p_offset limit p_limit) x; when 'shots' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select s.id,s.payload || jsonb_build_object('id',s.id,'sessionId',s.session_id,'review',r.state,'revision',r.revision) data from public.shots s join public.reviews r on r.shot_id=s.id and r.owner_id=s.owner_id where s.owner_id=u order by s.id offset p_offset limit p_limit) x; when 'imports' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,jsonb_build_object('id',id,'sessionId',session_id,'originalBase64',replace(encode(original,'base64'),E'\n',''),'fileHash',file_hash,'contentHash',content_hash,'parserVersion',parser_version) data from public.imports where owner_id=u order by id offset p_offset limit p_limit) x; when 'events' then select coalesce(jsonb_agg(x.data order by x.id),'[]') into result from (select id,jsonb_build_object('id',id,'shotId',shot_id,'before',before_state,'after',after_state,'createdAt',created_at,'undone',undone) data from public.review_events where owner_id=u order by id offset p_offset limit p_limit) x; else raise exception 'Invalid dataset table'; end case; return result; end $$;
create function private.restore_backup(p_dataset jsonb) returns void language plpgsql security definer set search_path='' as $$ declare u uuid:=private.lock_owner(); x jsonb; b bytea; sid uuid; shot uuid; imp public.imports%rowtype; canonical jsonb; shot_count integer; begin if exists(select 1 from public.sessions where owner_id=u) or exists(select 1 from public.shots where owner_id=u) then raise exception 'Restore requires empty dataset'; end if; if not coalesce(jsonb_typeof(p_dataset)='object' and (p_dataset->>'version') ~ '^[0-9]+$' and jsonb_typeof(p_dataset->'sessions')='array' and jsonb_typeof(p_dataset->'shots')='array' and jsonb_typeof(p_dataset->'imports')='array' and jsonb_typeof(p_dataset->'events')='array' and jsonb_array_length(p_dataset->'sessions')<=20000 and jsonb_array_length(p_dataset->'shots')<=100000 and jsonb_array_length(p_dataset->'imports')<=20000 and jsonb_array_length(p_dataset->'events')<=200000,false) then raise exception 'Invalid backup'; end if;
 for x in select value from jsonb_array_elements(p_dataset->'sessions') loop if not private.valid_session(x) then raise exception 'Invalid backup session'; end if; insert into public.sessions values((x->>'id')::uuid,u,x); end loop;
 for x in select value from jsonb_array_elements(p_dataset->'imports') loop sid:=(x->>'sessionId')::uuid; if not exists(select 1 from public.sessions where id=sid and owner_id=u) or not coalesce(jsonb_typeof(x->'originalBase64')='string' and jsonb_typeof(x->'fileHash')='string' and (x->>'fileHash') ~ '^[0-9a-f]{64}$' and jsonb_typeof(x->'contentHash')='string' and (x->>'contentHash') ~ '^[0-9a-f]{64}$' and jsonb_typeof(x->'parserVersion')='string',false) then raise exception 'Invalid backup import'; end if; b:=decode(x->>'originalBase64','base64'); if octet_length(b)>5242880 or encode(extensions.digest(b,'sha256'),'hex')<>x->>'fileHash' then raise exception 'Invalid backup bytes'; end if; insert into public.imports values((x->>'id')::uuid,u,sid,b,x->>'fileHash',x->>'contentHash',x->>'parserVersion'); end loop;
 for x in select value from jsonb_array_elements(p_dataset->'shots') loop sid:=(x->>'sessionId')::uuid; shot:=(x->>'id')::uuid; if not exists(select 1 from public.sessions where id=sid and owner_id=u) or not private.valid_shot(x) or not private.valid_review(x->'review') or (x->>'revision') !~ '^[0-9]+$' then raise exception 'Invalid backup shot'; end if; insert into public.shots values(shot,u,sid,x-'id'-'sessionId'-'review'-'revision'); insert into public.reviews values(shot,u,x->'review',(x->>'revision')::integer); end loop;
 for imp in select * from public.imports where owner_id=u loop
 select count(*),jsonb_build_object('headers',(select jsonb_agg(k) from jsonb_object_keys((select payload->'raw' from public.shots where owner_id=u and session_id=imp.session_id order by (payload->>'rowIndex')::integer limit 1)) k),'shots',jsonb_agg(payload order by (payload->>'rowIndex')::integer)) into shot_count,canonical from public.shots where owner_id=u and session_id=imp.session_id;
 if shot_count=0 or shot_count>20000 or exists(select 1 from (select (payload->>'rowIndex')::integer as n,row_number() over(order by (payload->>'rowIndex')::integer) as expected from public.shots where owner_id=u and session_id=imp.session_id) rows where n<>expected) or private.canonical_hash(canonical)<>imp.content_hash then raise exception 'Invalid backup content'; end if; perform private.validate_source(imp.original,canonical,imp.parser_version);
 end loop;
 for x in select value from jsonb_array_elements(p_dataset->'events') loop shot:=(x->>'shotId')::uuid; if not exists(select 1 from public.shots where id=shot and owner_id=u) or not private.valid_review(x->'before') or not private.valid_review(x->'after') then raise exception 'Invalid backup event'; end if; insert into public.review_events(id,owner_id,shot_id,before_state,after_state,created_at,undone) values((x->>'id')::uuid,u,shot,x->'before',x->'after',(x->>'createdAt')::timestamptz,coalesce((x->>'undone')::boolean,false)); end loop;
 if exists(select 1 from public.sessions s where owner_id=u and not exists(select 1 from public.imports i where i.session_id=s.id and i.owner_id=u)) then raise exception 'Session missing import'; end if; perform private.bump(u); end $$;
